306: <script>
307: (function(){
308:   const STORAGE_KEY = 'neu_calendar_events_v1';
309:   const monthNames = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
310: 
311:   let events = {};
312:   try{ events = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}'); }catch(e){ events = {}; }
313: 
314:   const today = new Date();
315:   let viewYear = today.getFullYear();
316:   let viewMonth = today.getMonth();
317:   let selected = fmt(today);
318: 
319:   function fmt(d){
320:     return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
321:   }
322: 
323:   // Feriados de Costa Rica: fechas fijas + Semana Santa (calculada con el algoritmo de Pascua)
324:   const holidayCache = {};
325:   function easterSunday(year){
326:     const a = year % 19, b = Math.floor(year/100), c = year % 100;
327:     const d = Math.floor(b/4), e = b % 4, f = Math.floor((b+8)/25);
328:     const g = Math.floor((b-f+1)/3), h = (19*a+b-d-g+15) % 30;
329:     const i = Math.floor(c/4), k = c % 4, l = (32+2*e+2*i-h-k) % 7;
330:     const m = Math.floor((a+11*h+22*l)/451);
331:     const month = Math.floor((h+l-7*m+114)/31);
332:     const day = ((h+l-7*m+114) % 31) + 1;
333:     return new Date(year, month-1, day);
334:   }
335:   function addDays(d, n){ const r = new Date(d); r.setDate(r.getDate()+n); return r; }
336:   function getHolidays(year){
337:     if(holidayCache[year]) return holidayCache[year];
338:     const easter = easterSunday(year);
339:     const set = new Set([
340:       year+'-01-01',
341:       fmt(addDays(easter,-3)),
342:       fmt(addDays(easter,-2)),
343:       year+'-04-11',
344:       year+'-05-01',
345:       year+'-07-25',
346:       year+'-08-02',
347:       year+'-08-15',
348:       year+'-09-15',
349:       year+'-12-25',
350:     ]);
351:     holidayCache[year] = set;
352:     return set;
353:   }
354:   function save(){
355:     try{ localStorage.setItem(STORAGE_KEY, JSON.stringify(events)); }catch(e){}
356:   }
357: 
358:   const grid = document.getElementById('grid');
359:   const marqueeTrack = document.getElementById('marqueeTrack');
360:   const selTitle = document.getElementById('selTitle');
361:   const eventList = document.getElementById('eventList');
362:   const progressFill = document.getElementById('progressFill');
363:   const progressCount = document.getElementById('progressCount');
364:   const toast = document.createElement('div'); toast.className='toast'; document.body.appendChild(toast);
365:   function showToast(msg){
366:     toast.textContent = msg; toast.classList.add('show');
367:     clearTimeout(showToast._t);
368:     showToast._t = setTimeout(()=> toast.classList.remove('show'), 3500);
369:   }
370: 
371:   // --- Iconos "pixel art" (estilo reloj digital) ---
372:   let iconColor = '#00F0FF';
373:   function drawPx(el, points, step, color){
374:     step = step || 3;
375:     el.style.boxShadow = points.map(p => (p[0]*step)+'px '+(p[1]*step)+'px 0 0 '+(color||iconColor)).join(',');
376:   }
377:   const ICONS = {
378:     sun: [[3,0],[1,1],[5,1],[2,2],[3,2],[4,2],[0,3],[2,3],[3,3],[4,3],[6,3],[2,4],[3,4],[4,4],[1,5],[5,5],[3,6]],
379:     moon: [[2,0],[3,0],[4,0],[1,1],[2,1],[0,2],[1,2],[0,3],[1,3],[0,4],[1,4],[1,5],[2,5],[2,6],[3,6],[4,6]],
380:     bellOn: [[3,0],[2,1],[3,1],[4,1],[2,2],[3,2],[4,2],[1,3],[2,3],[3,3],[4,3],[5,3],[1,4],[2,4],[3,4],[4,4],[5,4],[0,5],[1,5],[2,5],[3,5],[4,5],[5,5],[6,5],[3,6]],
381:     bellOffBody: [[3,0],[2,1],[3,1],[4,1],[2,2],[3,2],[4,2],[1,3],[2,3],[4,3],[5,3],[1,4],[4,4],[5,4],[0,5],[1,5],[2,5],[3,5],[4,5],[5,5],[6,5],[3,6]],
382:     bellOffSlash: [[0,6],[1,5],[2,4],[3,3],[4,2],[5,1],[6,0]],
383:     down: [[3,1],[3,2],[1,3],[2,3],[3,3],[4,3],[5,3],[2,4],[3,4],[4,4],[3,5]],
384:     up: [[3,1],[2,2],[3,2],[4,2],[1,3],[2,3],[3,3],[4,3],[5,3],[3,4],[3,5]]
385:   };
386:   drawPx(document.getElementById('exportIcon'), ICONS.down);
387:   drawPx(document.getElementById('importIcon'), ICONS.up);
388: 
389:   // --- Tema claro/oscuro ---
390:   const themeBtn = document.getElementById('themeBtn');
391:   const themeIcon = document.getElementById('themeIcon');
392:   function applyTheme(t){
393:     if(t){ document.documentElement.setAttribute('data-theme', t); }
394:     else{ document.documentElement.removeAttribute('data-theme'); }
395:     const isLight = t === 'light' || (!t && window.matchMedia('(prefers-color-scheme: light)').matches);
396:     iconColor = '#00F0FF';
397:     drawPx(themeIcon, isLight ? ICONS.sun : ICONS.moon);
398:   }
399:   let savedTheme = null;
400:   try{ savedTheme = localStorage.getItem('neu_theme'); }catch(e){}
401:   applyTheme(savedTheme);
402:   themeBtn.addEventListener('click', ()=>{
403:     const current = document.documentElement.getAttribute('data-theme') ||
404:       (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
405:     const next = current === 'dark' ? 'light' : 'dark';
406:     applyTheme(next);
407:     try{ localStorage.setItem('neu_theme', next); }catch(e){}
408:   });
409: 
410:   // --- Sonidos (dopamina) via Web Audio API, sin archivos externos ---
411:   let audioCtx = null;
412:   function getCtx(){
413:     if(!audioCtx){ try{ audioCtx = new (window.AudioContext||window.webkitAudioContext)(); }catch(e){} }
414:     return audioCtx;
415:   }
416:   function tone(freq, start, dur, type, gain){
417:     const ctx = getCtx(); if(!ctx) return;
418:     const osc = ctx.createOscillator(); const g = ctx.createGain();
419:     osc.type = type||'sine'; osc.frequency.value = freq;
420:     g.gain.setValueAtTime(0, ctx.currentTime+start);
421:     g.gain.linearRampToValueAtTime(gain||.18, ctx.currentTime+start+.02);
422:     g.gain.exponentialRampToValueAtTime(.0001, ctx.currentTime+start+dur);
423:     osc.connect(g); g.connect(ctx.destination);
424:     osc.start(ctx.currentTime+start); osc.stop(ctx.currentTime+start+dur+.05);
425:   }
426:   function playSuccessSound(){
427:     tone(523.25,0,.14,'triangle'); tone(659.25,.09,.14,'triangle'); tone(783.99,.18,.22,'triangle');
428:   }
429:   function playAlarmSound(){
430:     tone(880,0,.15,'sine',.22); tone(880,.22,.15,'sine',.22); tone(880,.44,.22,'sine',.22);
431:   }
432: 
433:   // --- Notificaciones / alarma 5 min antes ---
434:   const alarmBtn = document.getElementById('alarmBtn');
435:   let alarmsOn = false;
436:   try{ alarmsOn = localStorage.getItem('neu_alarms') === '1'; }catch(e){}
437:   const alarmIcon = document.getElementById('alarmIcon');
438:   function refreshAlarmBtn(){ alarmBtn.classList.toggle('active', alarmsOn); iconColor = '#00F0FF'; const s=3; if(alarmsOn){ drawPx(alarmIcon, ICONS.bellOn); }else{ const body=ICONS.bellOffBody.map(p=>(p[0]*s)+'px '+(p[1]*s)+'px 0 0 '+iconColor).join(','); const sc='#0088AA'; const slash=ICONS.bellOffSlash.map(p=>(p[0]*s)+'px '+(p[1]*s)+'px 0 0 '+sc).join(','); alarmIcon.style.boxShadow=body+','+slash; } }
439:   refreshAlarmBtn();
440:   alarmBtn.addEventListener('click', async ()=>{
441:     if(!alarmsOn){
442:       if('Notification' in window && Notification.permission !== 'granted'){
443:         try{ await Notification.requestPermission(); }catch(e){}
444:       }
445:       alarmsOn = true; showToast('Alarmas activadas: avisamos 5 min antes de cada tarea');
446:     }else{
447:       alarmsOn = false; showToast('Alarmas desactivadas');
448:     }
449:     try{ localStorage.setItem('neu_alarms', alarmsOn ? '1':'0'); }catch(e){}
450:     refreshAlarmBtn();
451:   });
452:   function triggerAlarm(ev){
453:     playAlarmSound();
454:     if('Notification' in window && Notification.permission === 'granted'){
455:       try{ new Notification('⏰ En 5 minutos: '+ev.title, {body: ev.time || ''}); }catch(e){}
456:     }
457:     showToast('⏰ En 5 min: '+ev.title);
458:   }
459:   function checkAlarms(){
460:     if(!alarmsOn) return;
461:     const now = new Date();
462:     let changed = false;
463:     Object.keys(events).forEach(dateKey=>{
464:       (events[dateKey]||[]).forEach(ev=>{
465:         if(!ev.time || ev.done || ev.notified) return;
466:         const evDate = new Date(dateKey+'T'+ev.time+':00');
467:         const diffMs = evDate - now;
468:         if(diffMs > 0 && diffMs <= 5*60*1000){
469:           triggerAlarm(ev); ev.notified = true; changed = true;
470:         }
471:       });
472:     });
473:     if(changed) save();
474:   }
475:   setInterval(checkAlarms, 20000);
476:   checkAlarms();
477: 
478:   // --- Marquee tipo rótulo LED: mes/año + micro-tareas del día seleccionado ---
479:   function updateMarquee(){
480:     const dayEvents = (events[selected]||[]);
481:     let text = monthNames[viewMonth].toUpperCase() + ' ' + viewYear;
482:     if(dayEvents.length){
483:       const abbr = dayEvents.slice(0,6).map(e=>{
484:         const t = e.title.length>16 ? e.title.slice(0,16)+'…' : e.title;
485:         return (e.done?'✓ ':'') + t + (e.time?' '+e.time:'');
486:       }).join('   •   ');
487:       text += '   •   ' + abbr;
488:     }
489:     const full = text + '   •   ' + text;
490:     marqueeTrack.textContent = full;
491:     const dur = Math.max(8, text.length * 0.16);
492:     marqueeTrack.style.animationDuration = dur + 's';
493:   }
494: 
495:   // --- Exportar / Importar respaldo ---
496:   document.getElementById('exportBtn').addEventListener('click', ()=>{
497:     const blob = new Blob([JSON.stringify(events,null,2)], {type:'application/json'});
498:     const url = URL.createObjectURL(blob);
499:     const a = document.createElement('a');
500:     a.href = url; a.download = 'micro-tareas-respaldo.json'; a.click();
501:     URL.revokeObjectURL(url);
502:     showToast('Respaldo descargado ✓');
503:   });
504:   document.getElementById('importInput').addEventListener('change', (e)=>{
505:     const file = e.target.files[0]; if(!file) return;
506:     const reader = new FileReader();
507:     reader.onload = ()=>{
508:       try{
509:         const data = JSON.parse(reader.result);
510:         events = Object.assign({}, events, data);
511:         save(); render();
512:         showToast('Respaldo importado ✓');
513:       }catch(err){ showToast('Archivo inválido'); }
514:     };
515:     reader.readAsText(file);
516:     e.target.value = '';
517:   });
518: 
519:   function render(){
520:     updateMarquee();
521:     grid.innerHTML = '';
522:     const first = new Date(viewYear, viewMonth, 1);
523:     const startOffset = first.getDay();
524:     const daysInMonth = new Date(viewYear, viewMonth+1, 0).getDate();
525:     const daysInPrev = new Date(viewYear, viewMonth, 0).getDate();
526:     const totalCells = Math.ceil((startOffset + daysInMonth)/7)*7;
527: 
528:     for(let i=0;i<totalCells;i++){
529:       const dayNum = i - startOffset + 1;
530:       let cellDate, muted = false;
531:       if(dayNum < 1){ cellDate = new Date(viewYear, viewMonth-1, daysInPrev + dayNum); muted = true; }
532:       else if(dayNum > daysInMonth){ cellDate = new Date(viewYear, viewMonth+1, dayNum - daysInMonth); muted = true; }
533:       else{ cellDate = new Date(viewYear, viewMonth, dayNum); }
534: 
535:       const key = fmt(cellDate);
536:       const isHoliday = getHolidays(cellDate.getFullYear()).has(key);
537:       const cell = document.createElement('div');
538:       cell.className = 'day' + (cellDate.getDay()===0 ? ' wd0' : '') + (isHoliday ? ' holiday' : '') + (muted ? ' muted' : '') + (key === fmt(today) ? ' today' : '') + (key === selected ? ' selected' : '');
539:       cell.setAttribute('role','button');
540:       cell.setAttribute('tabindex','0');
541:       cell.dataset.date = key;
542: 
543:       const num = document.createElement('span');
544:       num.textContent = cellDate.getDate();
545:       cell.appendChild(num);
546: 
547:       const dayEvents = events[key] || [];
548:       if(dayEvents.length){
549:         const dots = document.createElement('div');
550:         dots.className = 'dots';
551:         dayEvents.slice(0,3).forEach(()=>{
552:           const d = document.createElement('span'); d.className='dot'; dots.appendChild(d);
553:         });
554:         cell.appendChild(dots);
555:       }
556: 
557:       cell.addEventListener('click', ()=>{
558:         selected = key;
559:         if(muted){
560:           viewYear = cellDate.getFullYear();
561:           viewMonth = cellDate.getMonth();
562:         }
563:         render();
564:       });
565:       cell.addEventListener('keydown', (e)=>{
566:         if(e.key==='Enter' || e.key===' '){ e.preventDefault(); cell.click(); }
567:       });
568: 
569:       grid.appendChild(cell);
570:     }
571: 
572:     renderEvents();
573:   }
574: 
575:   function renderEvents(){
576:     const d = new Date(selected + 'T00:00:00');
577:     const label = d.toLocaleDateString('es-ES', {weekday:'long', day:'numeric', month:'long'});
578:     selTitle.textContent = label.charAt(0).toUpperCase() + label.slice(1);
579: 
580:     const progressLabel = document.querySelector('.progress-label');
581:     progressLabel.textContent = selected === fmt(today) ? 'Progreso de hoy' : 'Progreso del día';
582: 
583:     const list = (events[selected] || []).slice().sort((a,b)=> (a.time||'99:99').localeCompare(b.time||'99:99'));
584:     eventList.innerHTML = '';
585: 
586:     const total = list.length;
587:     const doneCount = list.filter(e => e.done).length;
588:     const pct = total ? Math.round((doneCount/total)*100) : 0;
589:     progressFill.style.width = pct + '%';
590:     progressCount.textContent = doneCount + '/' + total;
591: 
592:     if(!list.length){
593:       const empty = document.createElement('div');
594:       empty.className = 'empty';
595:       empty.textContent = 'No hay eventos este día. Toca + para agregar uno.';
596:       eventList.appendChild(empty);
597:       return;
598:     }
599:     list.forEach((ev, idx)=>{
600:       const row = document.createElement('div');
601:       row.className = 'neu-inset event' + (ev.done ? ' done' : '');
602:       row.innerHTML = `
603:         <div class="check" aria-label="Marcar como completada">✓</div>
604:         <div class="bar"></div>
605:         <div class="info">
606:           <div class="t"></div>
607:           <div class="h">${ev.time ? ev.time : 'Todo el día'}</div>
608:         </div>
609:         <button class="neu-btn del" aria-label="Eliminar evento">✕</button>
610:       `;
611:       row.querySelector('.t').textContent = ev.title;
612:       row.querySelector('.check').addEventListener('click', ()=>{
613:         ev.done = !ev.done;
614:         if(ev.done) playSuccessSound();
615:         save();
616:         renderEvents();
617:         updateMarquee();
618:         if(ev.done && total>0 && doneCount+1===total){
619:           setTimeout(()=>{ tone(1046.5,0,.12,'triangle'); tone(1318.5,.1,.12,'triangle'); tone(1568,.2,.3,'triangle'); showToast('🎉 ¡Todas las tareas completadas!'); }, 150);
620:         }
621:       });
622:       row.querySelector('.del').addEventListener('click', ()=>{
623:         events[selected] = events[selected].filter(e => e !== ev);
624:         if(events[selected].length === 0) delete events[selected];
625:         save();
626:         render();
627:       });
628:       eventList.appendChild(row);
629:     });
630:   }
631: 
632:   document.getElementById('prevBtn').addEventListener('click', ()=>{
633:     viewMonth--; if(viewMonth<0){viewMonth=11; viewYear--;} render();
634:   });
635:   document.getElementById('nextBtn').addEventListener('click', ()=>{
636:     viewMonth++; if(viewMonth>11){viewMonth=0; viewYear++;} render();
637:   });
638:   document.getElementById('todayBtn').addEventListener('click', ()=>{
639:     viewYear = today.getFullYear(); viewMonth = today.getMonth(); selected = fmt(today); render();
640:   });
641: 
642:   const overlay = document.getElementById('overlay');
643:   const evTitle = document.getElementById('evTitle');
644:   const evTime = document.getElementById('evTime');
645: 
646:   document.getElementById('addBtn').addEventListener('click', ()=>{
647:     evTitle.value=''; evTime.value='';
648:     overlay.classList.add('open');
649:     setTimeout(()=>evTitle.focus(), 50);
650:   });
651:   document.getElementById('cancelBtn').addEventListener('click', ()=> overlay.classList.remove('open'));
652:   overlay.addEventListener('click', (e)=>{ if(e.target === overlay) overlay.classList.remove('open'); });
653: 
654:   document.getElementById('saveBtn').addEventListener('click', ()=>{
655:     const title = evTitle.value.trim();
656:     if(!title) { evTitle.focus(); return; }
657:     if(!events[selected]) events[selected] = [];
658:     events[selected].push({ title, time: evTime.value || null });
659:     save();
660:     overlay.classList.remove('open');
661:     render();
662:     showToast('Tarea agregada ✓');
663:   });
664: 
665:   evTitle.addEventListener('keydown', (e)=>{ if(e.key==='Enter') document.getElementById('saveBtn').click(); });
666: 
667:   render();
668: })();
669: </script>
670: </body>
671: </html>

