/* ============================================================
   DÍA CERO — CSS compartido (index.html + dashboard.html)
   Bloque original EXTRAÍDO TEXTUAL del index.html.
   REGLA DE ORO: no se altera ningún estilo original.
   Las adiciones nuevas están al final, marcadas como "NUEVOS".
   ============================================================ */
:root{
  --bg:#CFD5DE;
  --surface:#ECF0F5;
  --surface-hi:#FBFCFE;
  --surface-lo:#E2E7EE;
  --shadow-l:#FFFFFF;
  --shadow-d:#A7B2C0;
  --shadow-d2:#8D99A9;
  --text:#33383F;
  --text-soft:#8590A0;
  --accent:#5C8DF2;
  --accent-soft:#DDE6FB;
  --danger:#E2685F;
  --sunday:#E2453D;
  --holiday:#2E9E5B;
  --neon:#00F0FF;
  --neon2:#FF2FD6;
  --neon-screen:#0A0E14;
  --bt-dia:#0A7C8C;
  --bt-cero:#C2188C;
  --bt-glow-dia:none;
  --bt-glow-cero:none;
  box-sizing:border-box;
  padding-top:env(safe-area-inset-top,0px);
  padding-bottom:env(safe-area-inset-bottom,0px);
}
@media (prefers-color-scheme: dark){
  :root:not([data-theme="light"]){
    --bg:#181B21; --surface:#242832; --surface-hi:#2A2F3A; --surface-lo:#1E222A; --shadow-l:#333844; --shadow-d:#0E1014; --shadow-d2:#08090C;
    --text:#EDEFF2; --text-soft:#8A93A3; --accent:#6E9CFB; --accent-soft:#2A3550;
    --sunday:#F2857D; --holiday:#5FC98A;
    --bt-dia:#00F0FF; --bt-cero:#FF2FD6;
    --bt-glow-dia:0 0 14px rgba(0,240,255,.5); --bt-glow-cero:0 0 14px rgba(255,47,214,.45);
  }
}
:root[data-theme="dark"]{
  --bg:#181B21; --surface:#242832; --surface-hi:#2A2F3A; --surface-lo:#1E222A; --shadow-l:#333844; --shadow-d:#0E1014; --shadow-d2:#08090C;
  --text:#EDEFF2; --text-soft:#8A93A3; --accent:#6E9CFB; --accent-soft:#2A3550;
  --sunday:#F2857D; --holiday:#5FC98A;
  --bt-dia:#00F0FF; --bt-cero:#FF2FD6;
  --bt-glow-dia:0 0 14px rgba(0,240,255,.5); --bt-glow-cero:0 0 14px rgba(255,47,214,.45);
}
*{margin:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent;}
html,body{height:100%;}
body{
  background:var(--bg);
  font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","Segoe UI",Roboto,sans-serif;
  color:var(--text);
  display:flex;
  justify-content:center;
  padding:32px 16px;
  min-height:100%;
}
.app{width:100%;max-width:900px;min-width:0;display:flex;flex-direction:column;gap:20px;}

.neu{background:linear-gradient(155deg, var(--surface-hi), var(--surface-lo));border-radius:24px;
  box-shadow:
    14px 14px 28px var(--shadow-d),
    -14px -14px 28px var(--shadow-l),
    6px 6px 10px var(--shadow-d2),
    inset 0 1px 0 rgba(255,255,255,.5);}
.neu-inset{background:linear-gradient(155deg, var(--surface-lo), var(--surface-hi));border-radius:16px;
  box-shadow:
    inset 5px 5px 10px var(--shadow-d),
    inset -5px -5px 10px var(--shadow-l),
    inset 2px 2px 4px var(--shadow-d2);}
.neu-btn{background:linear-gradient(155deg, var(--surface-hi), var(--surface-lo));border:none;border-radius:14px;color:var(--text);
  box-shadow:
    7px 7px 14px var(--shadow-d),
    -7px -7px 14px var(--shadow-l),
    3px 3px 6px var(--shadow-d2),
    inset 0 1px 0 rgba(255,255,255,.4);
  cursor:pointer;transition:box-shadow .15s ease, transform .1s ease;}
.neu-btn:active{box-shadow:inset 4px 4px 8px var(--shadow-d), inset -4px -4px 8px var(--shadow-l), inset 2px 2px 4px var(--shadow-d2);transform:translateY(1px);}
.neu-btn:focus-visible{outline:2px solid var(--accent);outline-offset:2px;}

header.neu{display:flex;align-items:center;justify-content:space-between;padding:16px 18px;gap:14px;min-width:0;}
.month-title{
  font-family:'Orbitron',sans-serif;
  font-size:20px;
  font-weight:700;
  letter-spacing:3px;
  min-width:240px;
  text-align:center;
  text-transform:uppercase;
  background:var(--neon-screen);
  border-radius:14px;
  padding:12px 0;
  color:var(--neon);
  text-shadow:0 0 4px var(--neon), 0 0 12px rgba(0,240,255,.6), 0 0 22px rgba(255,47,214,.35), 1px 0 0 var(--neon2);
  box-shadow:inset 2px 2px 5px rgba(0,0,0,.6), inset -1px -1px 3px rgba(255,255,255,.03);
  overflow:hidden;position:relative;
}
.marquee-track{display:inline-block;white-space:nowrap;padding-left:2px;animation:marquee 14s linear infinite;}
@keyframes marquee{from{transform:translateX(0)}to{transform:translateX(-50%)}}
.nav-group{display:flex;gap:14px;}
.toolbar{display:flex;gap:12px;padding:12px 16px;justify-content:center;}
.tool-btn{width:44px;height:44px;border-radius:14px;font-size:18px;display:flex;align-items:center;justify-content:center;position:relative;background:#000000;}
.pxicon{width:3px;height:3px;background:transparent;filter:drop-shadow(0 0 4px rgba(0,240,255,.6)); position:absolute; top:50%; left:50%; margin-left:-9px; margin-top:-9px;}
.tool-btn.active{color:var(--accent);}
.brand{display:flex;justify-content:space-between;align-items:center;padding-bottom:40px;gap:12px;min-width:0;width:100%;}
.brand-title{max-width:calc(100% - 108px);min-width:0;flex-shrink:1;white-space:nowrap;overflow:hidden;display:flex;align-items:baseline;gap:.3em;font-size:26px;font-weight:800;line-height:1;letter-spacing:.2px;}
.brand-title .bt-dia{color:var(--bt-dia);text-shadow:var(--bt-glow-dia);}
.brand-title .bt-cero{color:var(--bt-cero);text-shadow:var(--bt-glow-cero);}
.brand-title .bt-sep{color:var(--text-soft);font-weight:400;opacity:.8;}
.brand-title .bt-sub{color:var(--text-soft);font-size:.6em;font-weight:600;letter-spacing:.3px;}
.brand-btn{display:block;width:96px;padding:0;border:none;background:none;line-height:0;cursor:pointer;
  transition:transform .12s ease, opacity .18s ease;flex-shrink:0;}
.brand-btn img{display:block;width:100%;height:auto;}
.brand-btn:hover{transform:scale(1.05);}
.brand-btn:active{transform:scale(.96);opacity:.85;}
.brand-btn:focus-visible{outline:2px solid var(--accent);outline-offset:4px;border-radius:8px;}
.tool-btn input{position:absolute;inset:0;opacity:0;cursor:pointer;}
.toast{position:fixed;left:50%;bottom:24px;transform:translateX(-50%);background:var(--neon-screen);color:var(--neon);
  font-size:13px;font-weight:600;padding:12px 18px;border-radius:12px;box-shadow:0 6px 18px rgba(0,0,0,.4);
  opacity:0;pointer-events:none;transition:opacity .3s ease, transform .3s ease;z-index:50;text-align:center;max-width:80vw;}
.toast.show{opacity:1;transform:translateX(-50%) translateY(-6px);}
.nav-btn{
  width:46px;height:46px;display:flex;align-items:center;justify-content:center;
  font-family:'Orbitron',sans-serif;font-size:18px;font-weight:500;line-height:1;
