/* ============================================================
   DÍA CERO — Dashboard de métricas (estilo neumórfico puro)
   - Total completadas vs pendientes
   - Rendimiento por usuario (José vs Luis)
   - Velocidad de finalización (FechaCreacion → FechaFinalizacion)
   ============================================================ */
(function(){
  'use strict';

  const API = window.API;
  const USER_JOSE = 'José';
  const USER_LUIS = 'Luis';
  const $ = id => document.getElementById(id);

  function avgHours(list){
    const done = list.filter(t =>
      t.estado === 'completada' && t.fechaCreacion && t.fechaFinalizacion
    );
    if(!done.length) return null;
    let sum = 0;
    done.forEach(t=>{
      const ms = new Date(t.fechaFinalizacion) - new Date(t.fechaCreacion);
      sum += Math.max(0, ms) / 3600000; // horas, sin valores negativos
    });
    return sum / done.length;
  }

  function fmtDuration(h){
    if(h === null || isNaN(h)) return '—';
    if(h < 48) return h.toFixed(1) + ' h';
    return (h / 24).toFixed(1) + ' d';
  }

  function paint(tasks){
    const total = tasks.length;
    const done = tasks.filter(t => t.estado === 'completada');
    const pending = total - done.length;
    const pctGlobal = total ? Math.round((done.length / total) * 100) : 0;

    $('statDone').textContent = done.length;
    $('statPending').textContent = pending;
    $('statTotal').textContent = total;
    $('globalFill').style.width = pctGlobal + '%';
    $('globalCount').textContent = done.length + '/' + total;

    /* Rendimiento por usuario */
    [[USER_JOSE, 'jose'], [USER_LUIS, 'luis']].forEach(([user, key])=>{
      const mine = tasks.filter(t => t.responsable === user);
      const mineDone = mine.filter(t => t.estado === 'completada').length;
      const pct = mine.length ? Math.round((mineDone / mine.length) * 100) : 0;
      $(key + 'Fill').style.width = pct + '%';
      $(key + 'Meta').textContent = mineDone + '/' + mine.length + ' completadas · ' + pct + '%';
    });

    /* Velocidad de finalización */
    $('speedAvg').textContent = fmtDuration(avgHours(tasks));
    $('speedJose').textContent = fmtDuration(avgHours(tasks.filter(t => t.responsable === USER_JOSE)));
    $('speedLuis').textContent = fmtDuration(avgHours(tasks.filter(t => t.responsable === USER_LUIS)));

    $('dashNote').textContent = 'Última actualización: ' +
      new Date().toLocaleString('es-ES');
  }

  async function load(){
    $('dashNote').textContent = 'Sincronizando con la API…';
    try{
      const data = await API.getTasks();
      const tasks = Array.isArray(data.tasks) ? data.tasks : [];
      paint(tasks);
      if(!tasks.length){
        $('dashNote').textContent = 'Sin tareas todavía. Crea una desde el calendario y vuelve aquí.';
      }
    }catch(err){
      $('dashNote').textContent = '⚠ No se pudo cargar la API: ' + err.message;
    }
  }

  $('refreshBtn').addEventListener('click', (e)=>{
    e.preventDefault();
    load();
  });

  load();
})();

/* ============================================================
   DÍA CERO — /api/sync (Vercel Serverless Function)
   Puente SEGURO entre el frontend y Google Apps Script.
   El secreto (API_SECRET) NUNCA llega al navegador: solo vive
   en las variables de entorno de Vercel.

   Variables de entorno requeridas en Vercel:
     - GAS_URL    → URL de la app web de Apps Script (termina en /exec)
     - API_SECRET → misma clave que define la constante API_KEY en Code.gs

   Método GET  → lee tareas   (action=getTasks)
   Método POST → escribe      (action=create | update | delete | bulk)
   ============================================================ */

module.exports = async (req, res) => {
  const GAS_URL = process.env.GAS_URL;
  const API_SECRET = process.env.API_SECRET;

  if (!GAS_URL || !API_SECRET) {
    return res.status(500).json({
      ok: false,
      error: 'Configura GAS_URL y API_SECRET en las variables de entorno de Vercel.'
    });
  }

  try {
    if (req.method === 'GET') {
      const action = (req.query && req.query.action) || 'getTasks';
      const url =
        GAS_URL +
        (GAS_URL.includes('?') ? '&' : '?') +
        'key=' + encodeURIComponent(API_SECRET) +
        '&action=' + encodeURIComponent(action);

      const upstream = await fetch(url);
      const text = await upstream.text();

      res.setHeader('Content-Type', 'application/json; charset=utf-8');
      res.setHeader('Cache-Control', 'no-store');
      return res.status(200).send(text);
    }

    if (req.method === 'POST') {
      let body = req.body;
      if (typeof body === 'string') {
        try { body = JSON.parse(body); } catch (e) { body = {}; }
      }
      body = body || {};
      body.key = API_SECRET; // el secreto se inyecta solo, del lado del servidor

      const upstream = await fetch(GAS_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify(body)
      });
      const text = await upstream.text();

      res.setHeader('Content-Type', 'application/json; charset=utf-8');
      res.setHeader('Cache-Control', 'no-store');
      return res.status(200).send(text);
    }

    res.setHeader('Allow', 'GET, POST');
    return res.status(405).json({ ok: false, error: 'Método no permitido' });
  } catch (e) {
    return res.status(500).json({
      ok: false,
      error: 'Error de sincronización con Google Sheets.'
    });
  }
};

/**
 * ============================================================
 * DÍA CERO — Google Apps Script (Google Sheets como base de datos)
 * ============================================================
 * Pega este archivo en: Extensiones > Apps Script (dentro de tu hoja).
 *
 * PASOS:
 * 1. Cambia la constante API_KEY por tu propia clave secreta.
 * 2. Despliega: Implementar > Nueva implementación > Aplicación web
 *      - Ejecutar como: Yo
 *      - Quién tiene acceso: Cualquier persona
 * 3. Copia la URL pública (termina en /exec) → esa va en GAS_URL (Vercel).
 * 4. La misma API_KEY va en API_SECRET (Vercel).
 * NOTA: si modificas este script, vuelve a "Implementar > Administrar
 * implementaciones > Editar > Implementar" para generar una nueva versión.
 *
 * COLUMNAS DE LA HOJA "Tareas" (las crea automáticamente):
 *   A ID               → identificador único (ej. T-UUID)
 *   B Fecha            → fecha de la tarea, formato YYYY-MM-DD
 *   C Titulo           → texto de la tarea
 *   D Responsable      → "José" o "Luis"
 *   E Estado           → "pendiente" o "completada"
 *   F FechaCreacion    → ISO 8601 (ej. 2026-11-01T14:30:00.000Z)
 *   G FechaFinalizacion→ ISO 8601, se pone sola al completar; se borra al reabrir
 *   H Hora             → opcional, HH:MM (para las alarmas de 5 min)
 * ============================================================
 */

var SHEET_NAME = 'Tareas';
var API_KEY = 'DIA_CERO_CAMBIA_ESTA_CLAVE'; // ⚠️ cámbiala por una clave propia
var HEADERS = ['ID', 'Fecha', 'Titulo', 'Responsable', 'Estado', 'FechaCreacion', 'FechaFinalizacion', 'Hora'];

/* ---------- Utilidades ---------- */

function getSheet_() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sh = ss.getSheetByName(SHEET_NAME);
  if (!sh) sh = ss.insertSheet(SHEET_NAME);
  if (sh.getLastRow() === 0) {
    sh.appendRow(HEADERS);
    sh.setFrozenRows(1);
  }
  return sh;
}

function json_(obj) {
  return ContentService
    .createTextOutput(JSON.stringify(obj))
    .setMimeType(ContentService.MimeType.JSON);
}

function ok_(extra) { return json_(Object.assign({ ok: true }, extra || {})); }
function err_(msg) { return json_(ok_empty_(msg)); }
function ok_empty_(msg) { return { ok: false, error: msg }; } // solo para no perder el patrón

function authorized_(e) {
  return !!(e && e.parameter && String(e.parameter.key) === String(API_KEY));
}

function rowToTask_(r) {
  return {
    id: String(r[0] || ''),
    fecha: String(r[1] || ''),
    titulo: String(r[2] || ''),
    responsable: String(r[3] || 'José'),
    estado: String(r[4] || 'pendiente'),
    fechaCreacion: String(r[5] || ''),
    fechaFinalizacion: String(r[6] || ''),
    hora: String(r[7] || '')
  };
}

function taskToRow_(t) {
  return [t.id, t.fecha, t.titulo, t.responsable, t.estado, t.fechaCreacion, t.fechaFinalizacion, t.hora];
}

function readAll_() {
  var sh = getSheet_();
  var last = sh.getLastRow();
  if (last < 2) return [];
  var values = sh.getRange(2, 1, last - 1, 8).getValues();
  return values
    .filter(function (r) { return r[0] !== ''; })
    .map(rowToTask_);
}

function findRow_(sh, id) {
  var last = sh.getLastRow();
  if (last < 2) return -1;
  var ids = sh.getRange(2, 1, last - 1, 1).getValues();
  for (var i = 0; i < ids.length; i++) {
    if (String(ids[i][0]) === String(id)) return i + 2; // fila real en la hoja
  }
  return -1;
}

function newId_() {
  return 'T-' + Utilities.getUuid();
}

function sanitize_(raw) {
  raw = raw || {};
  var responsable = String(raw.responsable || 'José');
  if (responsable !== 'Luis') responsable = 'José';
  return {
    id: raw.id || newId_(),
    fecha: String(raw.fecha || ''),
    titulo: String(raw.titulo || '').slice(0, 120),
    responsable: responsable,
    estado: raw.estado === 'completada' ? 'completada' : 'pendiente',
    fechaCreacion: raw.fechaCreacion || new Date().toISOString(),
    fechaFinalizacion: raw.fechaFinalizacion || '',
    hora: String(raw.hora || '')
  };
}

/* ---------- LECTURA (GET) ---------- */

function doGet(e) {
  if (!authorized_(e)) return err_('No autorizado');
  var action = (e.parameter.action || 'getTasks');
  if (action === 'getTasks') {
    return ok_({ tasks: readAll_() });
  }
  return err_('Acción no válida: ' + action);
}

/* ---------- ESCRITURA (POST) ---------- */

function doPost(e) {
  if (!authorized_(e)) return err_('No autorizado');

  var body;
  try {
    body = JSON.parse(e.postData.contents);
  } catch (err) {
    return err_('JSON inválido');
  }

  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(20000); // evita escrituras simultáneas
  } catch (err) {
    return err_('La hoja está ocupada, intenta de nuevo');
  }

  try {
    var sh = getSheet_();
    var action = body.action;

    /* Crear una tarea */
    if (action === 'create') {
      var t = sanitize_(body.task);
      sh.appendRow(taskToRow_(t));
      return ok_({ task: t });
    }

    /* Crear muchas tareas (minuta / importar respaldo) */
    if (action === 'bulk') {
      var list = Array.isArray(body.tasks) ? body.tasks : [];
      if (!list.length) return err_('Lista vacía');
      var created = list.map(function (raw) { return sanitize_(raw); });
      var rows = created.map(taskToRow_);
      sh.getRange(sh.getLastRow() + 1, 1, rows.length, 8).setValues(rows);
      return ok_({ tasks: created });
    }

    /* Actualizar (cambiar estado, título, fecha, responsable u hora) */
    if (action === 'update') {
      var row = findRow_(sh, body.id);
      if (row < 0) return err_('Tarea no encontrada');
      var current = rowToTask_(sh.getRange(row, 1, 1, 8).getValues()[0]);
      var c = body.changes || {};

      if (typeof c.titulo === 'string' && c.titulo.trim()) current.titulo = c.titulo.slice(0, 120);
      if (typeof c.fecha === 'string' && c.fecha) current.fecha = c.fecha;
      if (typeof c.responsable === 'string' && c.responsable) current.responsable = c.responsable === 'Luis' ? 'Luis' : 'José';
      if (typeof c.hora === 'string') current.hora = c.hora;
      if (typeof c.estado === 'string' && (c.estado === 'pendiente' || c.estado === 'completada')) {
        current.estado = c.estado;
        // La fecha de finalización se gestiona sola para la métrica de velocidad
        if (c.estado === 'completada') {
          current.fechaFinalizacion = c.fechaFinalizacion || new Date().toISOString();
        } else {
          current.fechaFinalizacion = '';
        }
      }
      sh.getRange(row, 1, 1, 8).setValues([taskToRow_(current)]);
      return ok_({ task: current });
    }

    /* Eliminar */
    if (action === 'delete') {
      var r = findRow_(sh, body.id);
      if (r < 0) return err_('Tarea no encontrada');
      sh.deleteRow(r);
      return ok_({ deleted: String(body.id) });
    }

    return err_('Acción no válida: ' + action);
  } finally {
    lock.releaseLock();
  }
}

