const http = require('http');
const fs = require('fs');
const path = require('path');

const ROOT = '/home/sagan/Escritorio/INF01_WEBSITE/Clientes/IA INF01/Proyecto para contenido /Dia Cero';
const MIME = { '.html':'text/html', '.css':'text/css', '.js':'text/javascript', '.png':'image/png', '.jpeg':'image/jpeg', '.jpg':'image/jpeg', '.md':'text/plain' };

let tasks = [
  { id:'T-1', fecha:'2026-11-01', titulo:'Revisar propuesta', responsable:'José', estado:'completada', fechaCreacion:'2026-11-01T08:00:00.000Z', fechaFinalizacion:'2026-11-01T10:30:00.000Z', hora:'09:00' },
  { id:'T-2', fecha:'2026-11-01', titulo:'Llamar al cliente', responsable:'Luis', estado:'pendiente', fechaCreacion:'2026-11-01T08:10:00.000Z', fechaFinalizacion:'', hora:'15:00' },
  { id:'T-3', fecha:'2026-11-03', titulo:'Enviar informe semanal', responsable:'José', estado:'pendiente', fechaCreacion:'2026-11-01T09:00:00.000Z', fechaFinalizacion:'', hora:'' },
  { id:'T-4', fecha:'2026-11-04', titulo:'Diseño de portada', responsable:'Luis', estado:'completada', fechaCreacion:'2026-11-02T14:00:00.000Z', fechaFinalizacion:'2026-11-03T18:00:00.000Z', hora:'' }
];
let seq = 5;
const uuid = () => 'T-' + (seq++) + '-' + Math.random().toString(36).slice(2, 7);
const now = () => new Date().toISOString();

const server = http.createServer((req, res) => {
  const u = new URL(req.url, 'http://localhost');
  if (u.pathname === '/api/sync') {
    res.setHeader('Content-Type', 'application/json; charset=utf-8');
    if (req.method === 'GET') {
      return res.end(JSON.stringify({ ok: true, tasks }));
    }
    if (req.method === 'POST') {
      let raw = '';
      req.on('data', c => raw += c);
      req.on('end', () => {
        const body = JSON.parse(raw || '{}');
        if (body.action === 'create') {
          const t = Object.assign({ id: uuid(), fechaCreacion: now(), fechaFinalizacion: '', hora: '' }, body.task);
          tasks.push(t);
          return res.end(JSON.stringify({ ok: true, task: t }));
        }
        if (body.action === 'bulk') {
          const created = (body.tasks || []).map(t => Object.assign({ id: uuid(), fechaCreacion: now(), fechaFinalizacion: '', hora: '' }, t));
          tasks = tasks.concat(created);
          return res.end(JSON.stringify({ ok: true, tasks: created }));
        }
        if (body.action === 'update') {
          const t = tasks.find(x => x.id === body.id);
          if (!t) return res.end(JSON.stringify({ ok: false, error: 'no existe' }));
          Object.assign(t, body.changes || {});
          t.estado === 'completada'
            ? (t.fechaFinalizacion = t.fechaFinalizacion || now())
            : (t.fechaFinalizacion = '');
          return res.end(JSON.stringify({ ok: true, task: t }));
        }
        if (body.action === 'delete') {
          tasks = tasks.filter(x => x.id !== body.id);
          return res.end(JSON.stringify({ ok: true, deleted: body.id }));
        }
        return res.end(JSON.stringify({ ok: false, error: 'acción inválida' }));
      });
      return;
    }
    res.statusCode = 405;
    return res.end(JSON.stringify({ ok: false, error: 'method' }));
  }

  let file = path.join(ROOT, u.pathname === '/' ? 'index.html' : decodeURIComponent(u.pathname));
  fs.readFile(file, (err, data) => {
    if (err) { res.statusCode = 404; return res.end('404'); }
    res.setHeader('Content-Type', MIME[path.extname(file)] || 'application/octet-stream');
    res.end(data);
  });
});
server.listen(8787, () => console.log('mock en http://localhost:8787'));

