module.exports = async (req, res) => {
  jsonHeaders(res);

  if (req.method !== 'POST') {
    res.setHeader('Allow', 'POST');
    return res.status(405).json({ ok: false, error: 'Método no permitido' });
  }

  // Solo acepta llamadas desde el propio sitio (bloquea abuso desde otras páginas)
  const origin = req.headers && req.headers.origin;
  if (origin) {
    try {
      if (new URL(origin).host !== req.headers.host) {
        return res.status(403).json({ ok: false, error: 'Origen no permitido' });
      }
    } catch (e) { /* origin inválido → se ignora */ }
  }

  let body = req.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
  if (!body || typeof body !== 'object') body = {};

  const text = String(body.text || '').trim().slice(0, MAX_TEXT);
  if (!text) return res.status(400).json({ ok: false, error: 'Pega al menos una línea de texto' });

  const defaults = {
    fecha: isDate(body.fecha) ? body.fecha : todayUTC(),
    responsable: body.responsable === 'Luis' ? 'Luis' : 'José'
  };
  const hoy = isDate(body.hoy) ? body.hoy : defaults.fecha;

  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey) {
    return res.status(503).json({ ok: false, code: 'NO_KEY', error: 'Falta GEMINI_API_KEY en Vercel' });
  }

  try {
    const prompt = buildPrompt(text, defaults, hoy);
    const candidates = modelsToTry();
    const { model, text: rawText } = await callGemini(apiKey, candidates, prompt);
    const parsed = parseTasks(rawText);
    const tasks = sanitizeTasks(parsed, defaults);
    return res.status(200).json({ ok: true, model, tasks });
  } catch (e) {
    return res.status(502).json({ ok: false, error: 'La IA no respondió: ' + (e && e.message ? e.message : e) });
  }
};
```

