callGemini(model, prompt, apiKey):

```js
async function callGemini(apiKey, models, prompt) {
  let lastError = null;
  for (const model of models) {
    const url = 'https://generativelanguage.googleapis.com/v1beta/models/' + encodeURIComponent(model) + ':generateContent?key=' + encodeURIComponent(apiKey);
    const base = {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: {
        temperature: 0.1,
        maxOutputTokens: 4096,
        responseMimeType: 'application/json',
        responseSchema: RESPONSE_SCHEMA
      }
    };
    if (supportsThinking(model)) base.generationConfig.thinkingConfig = { thinkingBudget: 0 };

    let res, payload;
    try {
      res = await fetch(url, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(base) });
      payload = await res.json().catch(() => null);
    } catch (e) { lastError = e; continue; }

    if (!res.ok) {
      const msg = errMessage(payload, res.status);
      lastError = new Error(model + ': ' + msg);
      if (res.status === 404) continue;                       // modelo inexistente → siguiente
      if (res.status === 400 && /schema/i.test(msg)) {         // schema no soportado → reintentar sin él
        delete base.generationConfig.responseSchema;
        try {
          const res2 = await fetch(url, {... same body: JSON.stringify(base)});
          const payload2 = await res2.json().catch(()=>null);
          if (res2.ok) return { model, text: extractText(payload2) };
          lastError = new Error(model + ': ' + errMessage(payload2, res2.status));
        } catch (e2) { lastError = e2; }
      }
      continue;
    }
    const out = extractText(payload);
    if (out) return { model, text: out };
    lastError = new Error(model + ': respuesta vacía');
  }
  throw lastError || new Error('sin respuesta');
}
```

