function parseTasks(raw) {
  let s = String(raw || '').trim();
  s = s.replace(/^```(?:json)?/i, '').replace(/```$/,'').trim();
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a >= 0 && b > a) s = s.slice(a, b+1);
  const obj = JSON.parse(s);
  return Array.isArray(obj) ? obj : (obj && obj.tasks) || [];
}
