async function callGemini(key, candidates, payload) {
  let lastErr = null;
  for (const model of candidates) {
    try {
      const url = 'https://generativelanguage.googleapis.com/v1beta/models/' + model + ':generateContent?key=' + encodeURIComponent(key);
      const r = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      const data = await r.json().catch(()=>null);
      if (!r.ok) {
        const msg = data && data.error && data.error.message ? data.error.message : ('HTTP ' + r.status);
        lastErr = new Error(model + ': ' + msg);
        if (r.status === 404 || r.status === 400) continue; // modelo no existe → probar el siguiente
        throw lastErr;
      }
      return { model, data };
    } catch (e) { lastErr = e; }
  }
  throw lastErr || new Error('Gemini no respondió');
}
```

