api/minuta.js:

```js
/* ============================================================
   ONE ON ONE BUSINESS — /api/minuta (Vercel Serverless Function)
   Usa la API de Gemini para convertir el texto pegado en la
   minuta en tareas estructuradas.

   Variables de entorno requeridas en Vercel:
     - GEMINI_API_KEY → clave de Google AI Studio (aistudio.google.com/apikey)
   Opcional:
     - GEMINI_MODEL   → por defecto "gemini-3.6-flash"

   POST { text, responsable, fecha, hoy }
   →200 { ok: true, tasks: [ {titulo, fecha, hora, responsable} ] }
   → 200 { ok: false, code: 'NO_KEY', ... }  ← el frontend hace el modo por líneas
   ============================================================ */

const DEFAULT_MODEL = 'gemini-3.6-flash';
const MAX_TEXT = 6000;
const MAX_TASKS = 30;

module.exports = async (req, res) => {
  if (req.method !== 'POST') {
    res.setHeader('Allow', 'POST');
    return res.status(405).json({ ok: false, error: 'Método no permitido' });
  }

  // Protección básica: solo desde nuestro propio sitio
  const origin = req.headers.origin || '';
  const host = req.headers.host || '';
  if (origin && host && !origin.includes(host)) {
    return res.status(403).json({ ok: false, error: 'Origen no permitido' });
  }

  const GEMINI_API_KEY = process.env.GEMINI_API_KEY;
  if (!GEMINI_API_KEY) {
    return res.status(200).json({ ok: false, code: 'NO_KEY', error: 'GEMINI_API_KEY no configurada en Vercel' });
  }

  let body = req.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
  body = body || {};

  const text = String(body.text || '').trim().slice(0, MAX_TEXT);
  if (!text) return res.status(400).json({ ok: false, error: 'Texto vacío' });

  const responsable = body.responsable === 'Luis' ? 'Luis' : 'José';
  const fecha = isDate(body.fecha) ? body.fecha : todayStr();
  const hoy = isDate(body.hoy) ? body.hoy : fecha;

  try {
    const tasks = await askGemini(GEMINI_API_KEY, { text, responsable, fecha, hoy });
    return res.status(200).json({ ok: true, tasks });
  } catch (e) {
    return res.status(502).json({ ok: false, error: 'La IA no respondió: ' + (e && e.message ? e.message : e) });
  }
};
```

