```js
async function askGemini(key, { text, responsable, fecha, hoy }) {
  const model = process.env.GEMINI_MODEL || DEFAULT_MODEL;
  const url = 'https://generativelanguage.googleapis.com/v1beta/models/' + model + ':generateContent?key=' + encodeURIComponent(key);

  const payload = {
    contents: [{ role: 'user', parts: [{ text: buildPrompt(...) }] }],
    generationConfig: {
      temperature: 0.1,
      maxOutputTokens: 4096, // hmm, for flash-lite maybe default fine. Keep.
      responseMimeType: 'application/json',
      responseSchema: SCHEMA
    }
  };

  const r = await fetch(url, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(payload) });
  const data = await r.json().catch(()=>null);
  if (!r.ok) {
    const msg = data && data.error && data.error.message ? data.error.message : ('HTTP ' + r.status);
    throw new Error(msg);
  }
  const cand = data && data.candidates && data.candidates[0];
  const raw = cand && cand.content && cand.content.parts ? cand.content.parts.map(p=>p.text||'').join('') : '';
  return sanitizeTasks(raw, { responsable, fecha });
}
```

