```js
function sanitizeTasks(raw, defaults) {
  let data = String(raw||'').trim();
  data = data.replace(/^```(?:json)?/i,'').replace(/```$/,'').trim();
  let list = [];
  try {
    const parsed = JSON.parse(data);
    list = Array.isArray(parsed) ? parsed : (parsed && Array.isArray(parsed.tasks) ? parsed.tasks : []);
  } catch (e) {
    // último recurso: extraer el primer bloque {...}
    const m = data.match(/\[[\s\S]*\]/);
    if (m) { try { list = JSON.parse(m[0]); } catch(e2){} }
  }
  return list.slice(0, MAX_TASKS).map(t => ({
    titulo: String(t && t.titulo || '').trim().slice(0,120),
    fecha: isDate(t && t.fecha) ? t.fecha : defaults.fecha,
    hora: isTime(t && t.hora) ? t.hora : '',
    responsable: (t && t.responsable === 'Luis') ? 'Luis' : (t && t.responsable === 'José' ? 'José' : defaults.responsable)
  })).filter(t => t.titulo);
}
```

