document.getElementById('minutaProcessBtn').addEventListener('click', async ()=>{
  const raw = minutaText.value.trim();
  if(!raw){ minutaText.focus(); showToast('Pega al menos una línea de texto'); return; }

  const btn = document.getElementById('minutaProcessBtn');
  const labelOriginal = btn.textContent;
  btn.disabled = true;
  btn.textContent = 'Procesando…';

  const nowIso = new Date().toISOString();
  let payload = [];
  let iaFail = '';   // motivo del respaldo (vacío = todo fue con IA)

  try{
    /* 1) La IA convierte la minuta en tareas estructuradas */
    try{
      const data = await API.processMinuta({
        text: raw,
        responsable: minutaUser,
        fecha: selected,
        hoy: fmt(today)
      });
      payload = (data.tasks || []).map(t => normalizeTask({
        fecha: t.fecha || selected,
        titulo: String(t.titulo || '').slice(0, 120),
        responsable: (t.responsable === USER_LUIS) ? USER_LUIS
                   : (t.responsable === USER_JOSE) ? USER_JOSE
                   : minutaUser,
        estado: 'pendiente',
        fechaCreacion: nowIso,
        hora: String(t.hora || '')
      }));
    }catch(iaErr){
      /* 2) Respaldo: sin IA (sin clave o error) → una tarea por línea */
      iaFail = (iaErr && iaErr.code === 'NO_KEY') ? 'IA sin configurar en Vercel' : 'IA no disponible';
      payload = raw.split('\n').map(s => s.trim()).filter(Boolean).map(line => normalizeTask({
        fecha: selected,
        titulo: line.slice(0, 120),
        responsable: minutaUser,
        estado: 'pendiente',
        fechaCreacion: nowIso,
        hora: ''
      }));
    }

    if(!payload.length){ showToast('No se detectaron tareas en el texto'); return; }

    /* 3) Crear en lote por la API (Google Sheets) */
    const data = await API.bulkCreate(payload);
    (data.tasks || []).forEach(t => tasks.push(normalizeTask(t)));
    minutaOverlay.classList.remove('open');
    render();
    showToast(iaFail
      ? ('⚠ ' + iaFail + ' → ' + payload.length + ' tareas por líneas')
      : (payload.length + ' tareas creadas desde la minuta ✓'));
  }catch(err){
    showToast('⚠ ' + err.message);
  }finally{
    btn.disabled = false;
    btn.textContent = labelOriginal;
  }
});

