/* Tests de /api/minuta con Gemini simulado (sin clave real) */
const assert = require('assert');

function makeRes(){
  const res = { code: 0, body: null, headers: {} };
  res.status = c => { res.code = c; return res; };
  res.json = b => { res.body = b; return res; };
  res.setHeader = (k, v) => { res.headers[k] = v; };
  return res;
}

function geminiOk(tasks){
  return {
    ok: true,
    json: async () => ({
      candidates: [{ content: { parts: [{ text: JSON.stringify({ tasks }) }] } }]
    })
  };
}

async function run(){
  const modPath = require('path').join(__dirname, '..', '..', 'home', 'sagan', 'Escritorio', 'INF01_WEBSITE', 'Clientes', 'IA INF01', 'Proyecto para contenido ', 'Dia Cero', 'api', 'minuta.js');
  const handler = require('/home/sagan/Escritorio/INF01_WEBSITE/Clientes/IA INF01/Proyecto para contenido /Dia Cero/api/minuta.js');

  let passed = 0;
  const ok = (name) => { passed++; console.log('  ✓ ' + name); };

  const origFetch = global.fetch;
  const origKey = process.env.GEMINI_API_KEY;

  /* 1) Sin clave → 503 NO_KEY */
  delete process.env.GEMINI_API_KEY;
  let res = makeRes();
  await handler({ method: 'POST', body: { text: 'hola' } }, res);
  assert.strictEqual(res.code, 503);
  assert.strictEqual(res.body.code, 'NO_KEY');
  ok('sin GEMINI_API_KEY → 503 code:NO_KEY');

  /* 2) GET → 405 */
  res = makeRes();
  await handler({ method: 'GET' }, res);
  assert.strictEqual(res.code, 405);
  ok('GET → 405');

  /* 3) Texto vacío → 400 */
  process.env.GEMINI_API_KEY = 'test-key';
  res = makeRes();
  await handler({ method: 'POST', body: { text: '   ' } }, res);
  assert.strictEqual(res.code, 400);
  ok('texto vacío → 400');

  /* 4) Éxito con sanitización completa */
  global.fetch = async (url, opts) => {
    assert.ok(url.includes('gemini-3.5-flash-lite'), 'usa el modelo por defecto');
    assert.ok(url.includes('key=test-key'), 'la clave va por query param, no en el body');
    const body = JSON.parse(opts.body);
    assert.strictEqual(body.generationConfig.responseMimeType, 'application/json');
    assert.ok(body.generationConfig.responseSchema, 'envía responseSchema');
    assert.ok(body.contents[0].parts[0].text.includes('FECHA DE HOY: 2026-11-02'));
    return geminiOk([
      { titulo: '• Enviar propuesta al cliente', fecha: '2026-11-06', hora: '10:00', responsable: 'Luis' },
      { titulo: '1. Llamar al proveedor', fecha: 'no-fecha', hora: '3:30 PM', responsable: 'jose' },
      { titulo: '', fecha: '', hora: '', responsable: '' },          // sin título → se descarta
      { titulo: 'Revisar presupuesto', fecha: '2026-11-02', hora: '25:99', responsable: 'Otro' },
      ...Array.from({ length: 25 }, (_, i) => ({ titulo: 'T' + i, fecha: '2026-11-02', hora: '', responsable: 'Luis' }))
    ]);
  };
  res = makeRes();
  await handler({ method: 'POST', body: { text: 'minuta', responsable: 'José', fecha: '2026-11-02', hoy: '2026-11-02' } }, res);
  assert.strictEqual(res.code, 200);
  assert.strictEqual(res.body.ok, true);
  const t = res.body.tasks;
  assert.strictEqual(t.length, 20, 'tope de 20 tareas');
  assert.strictEqual(t[0].titulo, 'Enviar propuesta al cliente', 'bullets limpiados');
  assert.strictEqual(t[0].fecha, '2026-11-06');
  assert.strictEqual(t[0].hora, '10:00');
  assert.strictEqual(t[0].responsable, 'Luis');
  assert.strictEqual(t[1].fecha, '2026-11-02', 'fecha inválida → por defecto');
  assert.strictEqual(t[1].hora, '15:30', '3:30 PM → 15:30');
  assert.strictEqual(t[1].responsable, 'José', 'jose con/sin acento → José');
  assert.strictEqual(t[2].fecha, '2026-11-02', 'fecha por defecto');
  assert.strictEqual(t[2].hora, '', 'hora inválida → vacía');
  assert.strictEqual(t[2].responsable, 'José', 'responsable desconocido → por defecto');
  assert.ok(!t.some(x => x.titulo === ''), 'sin tareas vacías');
  ok('éxito: sanitización (título, fecha, hora AM/PM, responsable, tope 20)');

  /* 5) 400 por schema → reintenta sin responseSchema */
  let calls = 0;
  global.fetch = async (url, opts) => {
    calls++;
    const body = JSON.parse(opts.body);
    if (body.generationConfig.responseSchema) {
      return { ok: false, status: 400, json: async () => ({ error: { message: 'Invalid JSON payload: unknown field "responseSchema"' } }) };
    }
    return geminiOk([{ titulo: 'Tarea de prueba', fecha: '2026-11-03', hora: '', responsable: 'Luis' }]);
  };
  res = makeRes();
  await handler({ method: 'POST', body: { text: 'x', fecha: '2026-11-02' } }, res);
  assert.strictEqual(res.code, 200);
  assert.strictEqual(calls, 2, 'reintenta una vez sin schema');
  assert.strictEqual(res.body.tasks[0].titulo, 'Tarea de prueba');
  ok('400 por schema → reintenta sin responseSchema');

  /* 6) JSON malformado de Gemini → 502 (frontend hará modo líneas) */
  global.fetch = async () => ({
    ok: true,
    json: async () => ({ candidates: [{ content: { parts: [{ text: 'esto no es json {' }] } }] })
  });
  res = makeRes();
  await handler({ method: 'POST', body: { text: 'x' } }, res);
  assert.strictEqual(res.code, 502);
  assert.ok(/formato inesperado/.test(res.body.error));
  ok('respuesta malformada → 502 (cae al modo líneas)');

  /* 7) Error de API (clave inválida) → 502 con mensaje claro */
  global.fetch = async () => ({
    ok: false, status: 400,
    json: async () => ({ error: { message: 'API key not valid. Please pass a valid API key.' } })
  });
  res = makeRes();
  await handler({ method: 'POST', body: { text: 'x' } }, res);
  assert.strictEqual(res.code, 502);
  assert.ok(/API key not valid/.test(res.body.error));
  ok('clave inválida → 502 con mensaje de Gemini');

  /* 8) Timeout → 504 */
  global.fetch = async () => { const e = new Error('aborted'); e.name = 'AbortError'; throw e; };
  res = makeRes();
  await handler({ method: 'POST', body: { text: 'x' } }, res);
  assert.strictEqual(res.code, 504);
  ok('timeout → 504');

  /* 9) Sin candidatos (bloqueo) → 502 */
  global.fetch = async () => ({ ok: true, json: async () => ({ promptFeedback: { blockReason: 'SAFETY' } }) });
  res = makeRes();
  await handler({ method: 'POST', body: { text: 'x' } }, res);
  assert.strictEqual(res.code, 502);
  ok('respuesta vacía/bloqueada → 502');

  /* 10) Texto muy largo → se trunca a 8000 */
  let sentLen = 0;
  global.fetch = async (url, opts) => {
    sentLen = JSON.parse(opts.body).contents[0].parts[0].text.length;
    return geminiOk([]);
  };
  res = makeRes();
  await handler({ method: 'POST', body: { text: 'a'.repeat(20000) } }, res);
  assert.strictEqual(res.code, 200);
  assert.ok(sentLen < 9500, 'texto truncado (enviado ' + sentLen + ' chars)');
  ok('texto de 20k chars → truncado a 8000');

  global.fetch = origFetch;
  if (origKey === undefined) delete process.env.GEMINI_API_KEY; else process.env.GEMINI_API_KEY = origKey;

  console.log('\n' + passed + '/10 tests de api/minuta.js PASARON');
}

run().catch(e => { console.error('FALLO:', e.message); process.exit(1); });

