/* Test E2E de la Minuta con IA en el navegador (Chrome headless) */
const puppeteer = require('puppeteer-core');
const { spawn } = require('child_process');

const MOCK = '/tmp/opencode/mock-server.js';
const URL0 = 'http://localhost:8787/';
const MINUTA = 'Reunión con cliente\nEnviar propuesta el jueves a las 10\nLlamar al proveedor';

function startMock(env){
  return new Promise((resolve) => {
    const p = spawn('node', [MOCK], { env: Object.assign({}, process.env, env || {}) });
    p.stdout.on('data', d => { if (String(d).includes('mock en')) resolve(p); });
    p.stderr.on('data', d => process.stderr.write('[mock] ' + d));
  });
}
const stop = p => new Promise(r => { p.on('exit', r); p.kill(); });
const sleep = ms => new Promise(r => setTimeout(r, ms));

async function openMinuta(page){
  await page.goto(URL0, { waitUntil: 'networkidle0' });
  await page.click('#minutaBtn');
  await page.waitForSelector('#minutaOverlay.open', { visible: true });
  await page.$eval('#minutaText', (el, v) => { el.value = v; }, MINUTA);
}

async function procesar(page){
  await page.click('#minutaProcessBtn');
  let sawLoading = false;
  for (let i = 0; i < 80; i++) {
    const t = await page.$eval('#minutaProcessBtn', el => ({ txt: el.textContent, dis: el.disabled }));
    if (t.txt === 'Procesando…' && t.dis) { sawLoading = true; break; }
    await sleep(10);
  }
  return sawLoading;
}

async function main(){
  let passed = 0;
  const ok = n => { passed++; console.log('  ✓ ' + n); };
  const errors = [];

  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/google-chrome',
    headless: 'new',
    args: ['--no-sandbox', '--disable-gpu', '--window-size=1280,900']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 900 });
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));

  /* ========== ESCENARIO A: GEMINI_API_KEY configurada ========== */
  console.log('\n— Escenario A: IA disponible —');
  let mock = await startMock({});

  await page.goto(URL0, { waitUntil: 'networkidle0' });
  ok('index.html carga sin errores de consola');

  await page.click('#minutaBtn');
  await page.waitForSelector('#minutaOverlay.open', { visible: true });
  ok('modal de minuta abre');

  const label = await page.$eval('label[for="minutaText"]', el => el.textContent);
  if (!/IA/.test(label)) throw new Error('label no actualizado: ' + label);
  ok('label actualizado: "' + label + '"');

  await page.$eval('#minutaText', (el, v) => { el.value = v; }, MINUTA);
  await page.click('#minutaProcessBtn');

  const sawLoading = await (async () => {
    for (let i = 0; i < 80; i++) {
      const t = await page.$eval('#minutaProcessBtn', el => ({ txt: el.textContent, dis: el.disabled }));
      if (t.txt === 'Procesando…' && t.dis) return true;
      await sleep(10);
    }
    return false;
  })();
  if (!sawLoading) throw new Error('no se vio el estado "Procesando…"');
  ok('botón muestra "Procesando…" y queda deshabilitado');

  await page.waitForFunction(() => {
    const t = document.querySelector('.toast.show');
    return t && /tareas creadas desde la minuta ✓/.test(t.textContent);
  }, { timeout: 9000 });
  const toastA = await page.$eval('.toast.show', el => el.textContent);
  ok('toast de éxito con IA: "' + toastA + '"');

  const modalOpen = await page.$eval('#minutaOverlay', el => el.classList.contains('open'));
  if (modalOpen) throw new Error('el modal sigue abierto');
  const btnLabel = await page.$eval('#minutaProcessBtn', el => el.textContent);
  if (btnLabel !== 'Procesar') throw new Error('label no restaurado: ' + btnLabel);
  ok('modal cerrado y botón restaurado a "Procesar"');

  const dataA = await page.evaluate(() => fetch('/api/sync').then(r => r.json()));
  if (dataA.tasks.length !== 7) throw new Error('esperaba 7 tareas (4+3), hay ' + dataA.tasks.length);
  const creadas = dataA.tasks.slice(-3);
  if (!creadas.some(t => t.hora === '10:00')) throw new Error('la hora que "devolvió la IA" no llegó');
  if (!creadas.every(t => t.estado === 'pendiente' && t.fechaCreacion)) throw new Error('campos por defecto mal');
  ok('3 tareas creadas por bulkCreate (fecha/hora/responsable de la IA)');

  /* Ctrl+Enter también procesa */
  await page.click('#minutaBtn');
  await page.waitForSelector('#minutaOverlay.open', { visible: true });
  await page.$eval('#minutaText', (el, v) => { el.value = v; }, 'Otra tarea por atajo');
  await page.focus('#minutaText');
  await page.keyboard.down('Control'); await page.keyboard.press('Enter'); await page.keyboard.up('Control');
  await page.waitForFunction(() => {
    const t = document.querySelector('.toast.show');
    return t && /1 tareas creadas desde la minuta ✓/.test(t.textContent);
  }, { timeout: 9000 });
  ok('Ctrl+Enter procesa la minuta con IA');

  await stop(mock);

  /* ========== ESCENARIO B: sin GEMINI_API_KEY (fallback por líneas) ========== */
  console.log('\n— Escenario B: sin clave (fallback) —');
  mock = await startMock({ MOCK_NO_KEY: '1' });

  await openMinuta(page);
  await page.click('#minutaProcessBtn');
  await page.waitForFunction(() => {
    const t = document.querySelector('.toast.show');
    return t && /IA sin configurar en Vercel → 3 tareas por líneas/.test(t.textContent);
  }, { timeout: 9000 });
  const toastB = await page.$eval('.toast.show', el => el.textContent);
  ok('fallback visible: "' + toastB + '"');

  const dataB = await page.evaluate(() => fetch('/api/sync').then(r => r.json()));
  if (dataB.tasks.length !== 7) throw new Error('esperaba 7 tareas tras fallback, hay ' + dataB.tasks.length);
  ok('las 3 tareas se crearon igualmente por líneas');

  const btnB = await page.$eval('#minutaProcessBtn', el => el.textContent);
  if (btnB !== 'Procesar') throw new Error('botón no restaurado tras fallback');
  ok('botón restaurado tras el fallo de IA');

  /* Texto vacío → aviso, no crea nada */
  await page.click('#minutaBtn');
  await page.waitForSelector('#minutaOverlay.open', { visible: true });
  await page.$eval('#minutaText', el => { el.value = ''; });
  await page.click('#minutaProcessBtn');
  await page.waitForFunction(() => {
    const t = document.querySelector('.toast.show');
    return t && /Pega al menos una línea/.test(t.textContent);
  }, { timeout: 4000 });
  ok('texto vacío → aviso y no crea nada');
  await page.keyboard.press('Escape');

  /* ========== Dashboard compartido ========== */
  console.log('\n— Dashboard (js/api.js compartido) —');
  await page.goto(URL0.replace('8787', '8787').replace(/\/$/, '/dashboard.html'), { waitUntil: 'networkidle0' });
  await sleep(800);
  const dashBody = await page.evaluate(() => document.body.innerText.slice(0, 80));
  if (!dashBody.trim()) throw new Error('dashboard vacío');
  ok('dashboard.html carga con el api.js actualizado');

  await browser.close();
  await stop(mock);

  if (errors.length) {
    console.error('\nERRORES DE CONSOLA:\n' + errors.join('\n'));
    process.exit(1);
  }
  console.log('\n' + passed + '/10 comprobaciones E2E PASARON · 0 errores de consola');
}

main().catch(e => { console.error('\nFALLO:', e.message); process.exit(1); });

