/* Test en vivo: handler real de /api/minuta contra la API real de Gemini */
const handler = require('/home/sagan/Escritorio/INF01_WEBSITE/Clientes/IA INF01/Proyecto para contenido /Dia Cero/api/minuta.js');

const MINUTA = [
  'Reunión semanal del equipo. Todo bien, buen fin de semana a todos.',
  '- José debe enviar la propuesta al cliente mañana a las 10',
  '- Luis revisa el presupuesto del proveedor el jueves',
  '- Acordamos llamar al cliente el viernes por la tarde',
  'Gracias a todos, nos vemos.'
].join('\n');

function makeRes(){
  const res = { code: 0, body: null };
  res.status = c => { res.code = c; return res; };
  res.json = b => { res.body = b; console.log('HTTP', res.code, JSON.stringify(b, null, 2)); return res; };
  res.setHeader = () => {};
  return res;
}

(async () => {
  console.log('Probando con minuta real de 5 líneas (2 son ruido)...\n');
  const res = makeRes();
  await handler({
    method: 'POST',
    body: { text: MINUTA, responsable: 'José', fecha: '2026-11-02', hoy: '2026-11-02' }
  }, res);
  process.exit(res.code === 200 ? 0 : 1);
})().catch(e => { console.error('ERROR:', e); process.exit(1); });
